                      {hasAvatar ? 'Заменить' : 'Загрузить'}
                    </Button>
                    {hasAvatar ? (
                      <Button view="flat-danger" size="m" onClick={removeAvatar}>
                        <Icon data={TrashBin} size={16} />
                        Удалить
                      </Button>
                    ) : null}
