                  size="l"
                  width="max"
                  filterable
                  filterPlaceholder="Поиск по городу"
                  options={TIMEZONE_OPTIONS}
                  value={[values.timezone]}
                  onUpdate={([value]) => update('timezone', value)}
                  placeholder="Выберите часовой пояс"
                />
              </Field>
            </Flex>
          </Card>

